<?php require_once __DIR__ . '/../../includes/layout.php'; require_role(['Student','Admin']); $student=row('SELECT * FROM students WHERE user_id=?',[$_SESSION['user_id']]); render_header('My Attendance'); ?><div class="page-title"><div><h1>My Attendance</h1><p>Your recorded class attendance.</p></div></div><div class="row g-3 mb-3"><?php card_stat('Attendance Rate',($student['attendance_rate'] ?? 0).'%','fa-calendar-check','success','Overall'); card_stat('Risk Level',($student['risk_level'] ?? 'Not available'),'fa-heart-pulse','warning','Current'); ?></div><div class="panel"><table class="table"><thead><tr><th>Date</th><th>Subject</th><th>Status</th><th>Method</th></tr></thead><tbody><?php foreach(rows('SELECT a.*,sub.code FROM attendance a LEFT JOIN subjects sub ON sub.id=a.subject_id WHERE a.student_id=? ORDER BY a.date DESC',[($student['id'] ?? 0)]) as $a): ?><tr><td><?= e($a['date']) ?></td><td><?= e($a['code']) ?></td><td><?= e($a['status']) ?></td><td><?= e($a['method']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php render_footer(); ?>
